package io.github.danielalmeida19.orchestranode.annotations;

import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;

/**
 * Annotation to sinalize a Field to be the ID of a managed Collection
 *
 * @author Daniel
 */
@Target(ElementType.FIELD)
@Retention(RetentionPolicy.RUNTIME)
public @interface CollectionId {

    /**
     * Is the policy of the filling of the value, that can be autogenerated or
     * manually setted
     *
     * The default value is DB_AUTO_GENERATED
     */
    FillingPolicy fillingPolicy() default FillingPolicy.DB_AUTO_GENERATED;
}
